/* Public Nesine Statistics endpoints used by its published Statistics app.
 * SLU is a PREVIOUS SAME-TOURNAMENT XI when ISML=false. APVZ is age privacy. */
function pp_nesine_json(string $url,array $cfg,DateTimeImmutable $now,?callable $fetcher=null):array {
 static $calls=0,$start=null;$start=$start??microtime(true);
 if(!preg_match('~^https://apistats\.nesine\.com/api/v(?:3/HeadToHead/\d{1,12}/(?:Header|LastMatches|CompetitionHistory)|4/HeadToHead/\d{1,12}/LineUps)$~D',$url))throw new RuntimeException('Invalid Nesine public endpoint');
 $file=$cfg['storage_dir'].'/source-nesine-'.hash('sha256',$url).'.json';$old=pp_read($file);$at=strtotime($old['fetchedAt']??'')?:0;$ttl=str_ends_with($url,'/LineUps')?90:(str_ends_with($url,'/Header')?180:3600);
 if($at&&$at<=$now->getTimestamp()&&$now->getTimestamp()-$at<$ttl)return $old;
 try{if(isset($cfg['_lineup_deadline'])&&microtime(true)>$cfg['_lineup_deadline']-1)throw new RuntimeException('Lineup deadline');if(++$calls>($cfg['nesine_request_budget']??8)||microtime(true)-$start>($cfg['nesine_max_seconds']??20))throw new RuntimeException('Nesine request budget');$net=$cfg;$net['source_hosts']=array_values(array_unique(array_merge($cfg['source_hosts']??[],['apistats.nesine.com'])));$net['request_timeout_seconds']=isset($cfg['_lineup_deadline'])?max(1,min(4,(int)($cfg['_lineup_deadline']-microtime(true)))):4;$net['max_download_bytes']=2000000;$doc=$fetcher?$fetcher($url,$net):pp_fetch($url,$net);if(!is_array($doc)||($doc['sc']??0)!==200||!is_array($doc['d']??null))throw new RuntimeException('Nesine data unavailable');$out=['document'=>$doc,'fetchedAt'=>$now->format(DATE_ATOM),'url'=>$url,'stale'=>false];pp_write($file,$out);return $out;
 }catch(Throwable $e){pp_lineup_trace('Nesine','unavailable',$e->getMessage());if($at&&$at<=$now->getTimestamp()&&$now->getTimestamp()-$at<21600)return array_merge($old,['stale'=>true]);throw $e;}
}
function pp_nesine_name(string $name):string {$s=pp_public_name($name);return ['goztepeizmir'=>'goztepe','galatasarayistanbul'=>'galatasaray','manchesterutd'=>'manchesterunited','manchestercity'=>'manchestercity'][$s]??$s;}
function pp_nesine_header(array $doc,array $m):?array {
 $h=$doc['d']??[];$kick=strtotime($m['kickoff']??'');if(($doc['sc']??0)!==200||!$kick||($h['SID']??0)!==1||!is_int($h['MID']??null)||!is_int($h['BID']??null))return null;$local=(new DateTimeImmutable('@'.$kick))->setTimezone(new DateTimeZone('Europe/Istanbul'));$months=[1=>'Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'];$date=$local->format('j').' '.$months[(int)$local->format('n')];$year=(int)$local->format('Y')-((int)$local->format('n')<7?1:0);$season=substr((string)$year,-2).'/'.substr((string)($year+1),-2);
 if(($h['MDTime']??'')!==$date||($h['MDHour']??'')!==$local->format('H:i')||($h['TOUR']['SEA']??'')!==$season)return null;
 $ids=['tr.1'=>52,'en.1'=>17,'de.1'=>35,'it.1'=>23,'es.1'=>8,'fr.1'=>34];$code=$m['competitionId']??'';if(isset($ids[$code])){if(($h['TOUR']['TID']??0)!==$ids[$code])return null;}else{$cups=['ucl'=>'sampiyonlarligi','uel'=>'avrupaligi','uecl'=>'konferansligi'];if(!isset($cups[$code])||!str_contains(pp_nesine_name($h['TOUR']['N']??''),$cups[$code]))return null;}
 foreach(['home'=>'HT','away'=>'AT']as$s=>$key){if(count($h[$key]??[])!==1)return null;$t=$h[$key][0];if(!is_int($t['TID']??null)||pp_nesine_name($t['N']??'')!==pp_nesine_name($m[$s]['name']??''))return null;}return $h;
}
function pp_nesine_target(array $m,array $cfg,DateTimeImmutable $now,?callable $fetcher=null):?array {
 $kick=strtotime($m['kickoff']??'');if(!$kick)return null;
 // Mackolik's public iddaaCode is an independently discoverable Nesine route.
 // Never trust the code alone: verify season, competition, teams and kickoff.
 try{if(!($cfg['mackolik_enabled']??false))throw new RuntimeException('Mackolik disabled');$date=(new DateTimeImmutable('@'.$kick))->setTimezone(new DateTimeZone('Europe/Istanbul'))->format('Y-m-d');$board=pp_mackolik_page(pp_mackolik_day_url($date),$cfg,$now,$fetcher);$event=pp_mackolik_event($board['document'],$m);$candidate=(string)($event['iddaaCode']??'');if(preg_match('/^\d{1,12}$/D',$candidate)){$capture=pp_nesine_json('https://apistats.nesine.com/api/v3/HeadToHead/'.$candidate.'/Header',$cfg,$now,$fetcher);$header=pp_nesine_header($capture['document'],$m);if($header)return ['id'=>$candidate,'header'=>$header,'capture'=>$capture,'discovery'=>'Mackolik verified iddaaCode'];}}catch(Throwable $e){}
 $day=strtotime(gmdate('Y-m-d',$kick).'T00:00:00Z');$d=pp_misli_json('https://apivx.misli.com/api/web/v1/statistics/sport/SOCCER/matches/old?fromdate='.($day*1000),$cfg,$now,$fetcher);$e=pp_misli_event($d['document'],$m);if(!$e)return null;$id=(string)$e['sgId'];$page=pp_nesine_json('https://apistats.nesine.com/api/v3/HeadToHead/'.$id.'/Header',$cfg,$now,$fetcher);$h=pp_nesine_header($page['document'],$m);return $h?['id'=>$id,'header'=>$h,'capture'=>$page]:null;
}
function pp_nesine_match_player(array $p,array $rows):?array {
 $name=pp_nesine_name($p['name']??$p['PNM']??'');$number=$p['shirtNumber']??$p['number']??$p['SNB']??null;$found=[];foreach($rows as$r){$rn=pp_nesine_name($r['PNM']??'');$last=pp_nesine_name((string)preg_replace('/^.*\s/u','',$r['PNM']??''));$pl=pp_nesine_name((string)preg_replace('/^.*\s/u','',$p['name']??$p['PNM']??''));if($rn===$name||($number!==null&&(string)$number===(string)($r['SNB']??'')&&$last&&$last===$pl))$found[]=$r;}return count($found)===1?$found[0]:null;
}
function pp_nesine_participation(array $p,array $evidence):array {
 $r=pp_nesine_match_player($p,$evidence['players']??[]);if(!$r)return $p;
 foreach(['SXI'=>'seasonStarts','TMT'=>'appearances']as$key=>$to){$v=$r[$key]??'-';if(preg_match('/^\d{1,3}$/D',(string)$v)||$v==='-')$p[$to]=$v==='-'?0:(int)$v;}
 $p['participationSource']='Nesine verified current-season squad';$p['participationAsOf']=$evidence['asOf']??null;$p['providerIds']['nesine']=(string)$r['PID'];
 if(is_numeric($r['HEI']??null)&&$r['HEI']>=1.45&&$r['HEI']<=2.15){$w=is_numeric($r['WEI']??null)&&(float)$r['WEI']>=40&&(float)$r['WEI']<=125?(float)$r['WEI']:null;$p['physical']=['heightCm'=>round((float)$r['HEI']*100,1),'weightKg'=>$w,'verifiedMeasurements'=>true,'source'=>'Nesine current squad SI measurements'];}return $p;
}
function pp_nesine_roles(string $formation,array $bands,array $rows):?array {
 $positions=[];foreach($bands as$line=>$ids){foreach($ids as$i=>$id){if(isset($positions[$id]))return null;$positions[$id]=['x'=>($i+1)/(count($ids)+1),'y'=>.08+$line*.17];}}
 $starters=[];$seen=[];foreach($rows as$p)if(isset($positions[$p['PID']??null])&&($p['STR']??false)===true){if(isset($seen[(string)$p['PID']]))return null;$seen[(string)$p['PID']]=true;$starters[]=['id'=>(string)$p['PID'],'name'=>$p['PNM'],'shirtNumber'=>$p['SNB'],'verticalLayout'=>$positions[$p['PID']]];}
 $current=array_map('strval',array_keys($seen));$required=array_map('strval',array_keys($positions));sort($current);sort($required);return count($positions)===11&&$current===$required?pp_public_roles($formation,$starters):null;
}
function pp_nesine_enrich(array $m,array $teams,array $cfg,DateTimeImmutable $now,?callable $fetcher=null):array {
 try{$target=pp_nesine_target($m,$cfg,$now,$fetcher);if(!$target)return $teams;$capture=pp_nesine_json('https://apistats.nesine.com/api/v4/HeadToHead/'.$target['id'].'/LineUps',$cfg,$now,$fetcher);$d=$capture['document']['d'];$before=$now->getTimestamp()<(strtotime($m['kickoff']??'')?:0);
  foreach(['home'=>'HT','away'=>'AT']as$side=>$key){$i=$side==='home'?0:1;$raw=$d[$key]??[];if(($raw['TID']??null)!==$target['header'][$key][0]['TID']||pp_nesine_name($raw['N']??'')!==pp_nesine_name($m[$side]['name']??'')||!is_bool($raw['APVZ']??null)||!is_bool($d['ISML']??null)||count($raw['LUP']??[])<11)continue;
   $evidence=['players'=>$raw['LUP'],'asOf'=>$capture['fetchedAt'],'url'=>$capture['url'],'providerTeamId'=>$raw['TID'],'announced'=>$d['ISML']];$teams[$i]=$teams[$i]??[];$teams[$i]['nesineRoster']=$evidence;if(!empty($raw['MN']['N'])&&($before||$evidence['announced'])){$manager=['name'=>$raw['MN']['N'],'source'=>'Nesine current match metadata','asOf'=>$capture['fetchedAt'],'basis'=>$evidence['announced']?'exact-match':'current-club','url'=>$capture['url']];if($before)pp_current_coach_save($m,$side,$manager,$cfg);if(($teams[$i]['source']['status']??'')!=='provider-lineup'||$evidence['announced'])$teams[$i]['coach']=$manager;}
   foreach(['players','bench']as$list)foreach($teams[$i][$list]??[]as$j=>$p)$teams[$i][$list][$j]=pp_nesine_participation($p,$evidence);
   // Preserve confirmed/probable exact-match XIs. A previous XI is only a fallback.
   $actual=$evidence['announced'];$existing=$teams[$i]['source']['status']??'';if($existing==='provider-lineup'||(!$actual&&($existing==='provider-predicted'||!$before)))continue;
   $slu=$raw['SLU']??[];$sourceRows=$actual?array_values(array_filter($raw['LUP'],fn($p)=>($p['STR']??false)===true)):($slu['SLUP']??[]);$xi=pp_nesine_roles($slu['FMN']??'',$slu['FMNPIDS']??[],$sourceRows);if(!$xi)continue;
   $pool=array_merge($teams[$i]['players']??[],$teams[$i]['bench']??[]);$players=[];$seen=[];foreach($xi as$p){$current=pp_nesine_match_player($p,$raw['LUP']);if(!$actual&&$current&&pp_lineup_out($current)){$players=[];break;}$linked=pp_misli_player($p,$pool,(string)$raw['TID'],(string)$target['header']['TOUR']['SEA'],$p['_role']);if(!$linked)continue;if(str_starts_with($linked['id'],'ms-'))$linked['id']='ns-'.$p['id'];$linked=pp_nesine_participation($linked,$evidence);$linked['identitySource']='Nesine current squad + previous same-tournament XI';$players[]=$linked;$seen[(string)$p['id']]=true;}if(count($players)!==11)continue;
   $bench=[];foreach($raw['LUP']as$r){if(isset($seen[(string)($r['PID']??'')]))continue;$reason=pp_public_name($r['MTMR']??'');if(($r['IMTM']??false)&&!str_contains($reason,'supheli')&&!str_contains($reason,'doubtful'))continue;$p=pp_misli_player(['name'=>$r['PNM']??'','shirtNumber'=>$r['SNB']??null],$pool,(string)$raw['TID'],(string)$target['header']['TOUR']['SEA'],pp_players_role($r['PST']??'')??'MID');if(!$p)continue;if(str_starts_with($p['id'],'ms-'))$p['id']='ns-'.$r['PID'];$bench[]=pp_nesine_participation($p,$evidence);}usort($bench,fn($a,$b)=>(($b['seasonStarts']??0)<=>($a['seasonStarts']??0))?:(($b['appearances']??0)<=>($a['appearances']??0)));
   $teams[$i]=array_merge($teams[$i],['teamId'=>(string)($m[$side]['espnId']??$teams[$i]['teamId']??''),'formation'=>$slu['FMN'],'players'=>$players,'bench'=>array_slice($bench,0,pp_bench_limit($m['competitionId']??'')),'coach'=>!empty($raw['MN']['N'])?['name'=>$raw['MN']['N'],'source'=>'Nesine','asOf'=>$capture['fetchedAt'],'basis'=>$actual?'exact-match':'current-club','url'=>$capture['url']]:$teams[$i]['coach']??null,'source'=>['name'=>'Nesine','status'=>$actual?'provider-lineup':'estimated-from-recent-start','selectionVersion'=>PP_LINEUP_SELECTION_VERSION,'selectionBasis'=>$actual?'exact-match-announced':'previous-same-tournament-XI-with-season-participation','benchStatus'=>$actual?'match-bench':'expected-from-current-squad','asOf'=>$capture['fetchedAt'],'url'=>$capture['url'],'providerMatchId'=>$target['header']['MID'],'stale'=>$capture['stale']||$target['capture']['stale']]]);
  }
 }catch(Throwable $e){}return $teams;
}
function pp_nesine_history_team(array $team,array $header,array $m):array {foreach(['home'=>'HT','away'=>'AT']as$s=>$key)if(($team['TID']??null)===$header[$key][0]['TID']&&pp_nesine_name($team['N']??'')===pp_nesine_name($header[$key][0]['N']))return $m[$s];return pp_team($team['N']);}
function pp_nesine_history_rows(array $doc,array $header,array $m,DateTimeImmutable $now,string $url):array {
 $rows=[];$cut=min($now->getTimestamp(),strtotime($m['kickoff'])?:0);$months=['Ocak'=>1,'Şubat'=>2,'Mart'=>3,'Nisan'=>4,'Mayıs'=>5,'Haziran'=>6,'Temmuz'=>7,'Ağustos'=>8,'Eylül'=>9,'Ekim'=>10,'Kasım'=>11,'Aralık'=>12];
 $walk=function($x)use(&$walk,&$rows,$cut,$months,$header,$m,$now,$url){if(!is_array($x))return;if(isset($x['MID'],$x['SID'],$x['HT'],$x['AT'],$x['SC'])){if($x['SID']!==1||!preg_match('/^(\d{1,2}) ([^ ]+) (\d{4})$/u',$x['POFMD']??'',$d)||!isset($months[$d[2]]))return;$date=sprintf('%04d-%02d-%02d',(int)$d[3],$months[$d[2]],(int)$d[1]);$t=strtotime($date.'T23:59:59+03:00');if(!$t||$t>=$cut||$cut-$t>550*86400)return;$same=false;foreach(['HT','AT']as$side)foreach(['HT','AT']as$target)if(($x[$side]['TID']??null)===$header[$target][0]['TID']&&pp_nesine_name($x[$side]['N']??'')===pp_nesine_name($header[$target][0]['N']))$same=true;if(!$same)return;$scores=array_values(array_filter($x['SC'],fn($s)=>($s['OBI']??null)===99&&($s['TY']??null)===2));if(count($scores)!==1||count(array_filter($x['SC'],fn($s)=>!in_array($s['OBI']??0,[1,99],true))))return;$r=$scores[0];if(!is_int($r['HTS']??null)||!is_int($r['ATS']??null)||min($r['HTS'],$r['ATS'])<0||max($r['HTS'],$r['ATS'])>30)return;$rows[]=['date'=>$date,'home'=>pp_nesine_history_team($x['HT'],$header,$m),'away'=>pp_nesine_history_team($x['AT'],$header,$m),'competitionId'=>'verified-public-history','season'=>'','result'=>['home'=>$r['HTS'],'away'=>$r['ATS']],'source'=>['name'=>'Nesine','url'=>$url,'providerMatchId'=>$x['MID'],'capturedAt'=>$now->format(DATE_ATOM),'scoreBasis'=>'completed-history-normal-time-OBI99-TY2']];return;}foreach($x as$v)if(is_array($v))$walk($v);};$walk($doc['d']??[]);return $rows;
}
function pp_ap_collect_nesine(array $m,array $cfg,DateTimeImmutable $now,?callable $fetcher=null):array {
 $t=pp_nesine_target($m,$cfg,$now,$fetcher);if(!$t)return ['rows'=>[],'status'=>'fixture-not-matched'];$url='https://apistats.nesine.com/api/v3/HeadToHead/'.$t['id'].'/LastMatches';$p=pp_nesine_json($url,$cfg,$now,$fetcher);$rows=pp_nesine_history_rows($p['document'],$t['header'],$m,$now,$url);return ['rows'=>$rows,'status'=>$rows?'verified-completed-history':'no-verified-completed-history','url'=>$url,'asOf'=>$p['fetchedAt']];
}
